
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_msrpbel_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_msrpbel", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.541608231871922e+00, -4.452704185393969e+00, -4.328190206616775e+00, -4.155839678081693e+00, -3.921275558610789e+00, -3.609714015333329e+00, -3.210096973170717e+00, -2.722584498753135e+00, -2.167885697695476e+00, -1.574921057215122e+00, -1.020399804280863e+00, -6.771521793214763e-01, -6.031764404476505e-01, -5.096856285512628e-01, -3.659149127652666e-01, -2.324806928185300e-01, -1.362621835828148e-01, -5.042684721453417e-02, -1.082147707426292e-02, -1.216216050001396e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


